
document.addEventListener("DOMContentLoaded", function () {

    const form = document.getElementById("form-pessoa");
        const tabela = document.getElementById("tabela-pessoas");
            const erro = document.getElementById("erro");

                const nome = document.getElementById("input-nome");
                    const idade = document.getElementById("input-idade");
                        const altura = document.getElementById("input-altura");
                            const peso = document.getElementById("input-peso");

                                let pessoas = [];
                                    let editando = -1;

                                        form.addEventListener("submit", function (event) {
                                                event.preventDefault();

                                                        if (
                                                                    nome.value.trim() === "" ||
                                                                                idade.value === "" ||
                                                                                            altura.value === "" ||
                                                                                                        peso.value === ""
                                                                                                                ) {
                                                                                                                            erro.textContent = "Preencha todos os campos!";
                                                                                                                                        erro.hidden = false;
                                                                                                                                                    return;
                                                                                                                                                            }

                                                                                                                                                                    const pessoa = {
                                                                                                                                                                                nome: nome.value.trim(),
                                                                                                                                                                                            idade: Number(idade.value),
                                                                                                                                                                                                        altura: Number(altura.value),
                                                                                                                                                                                                                    peso: Number(peso.value)
                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                    if (
                                                                                                                                                                                                                                                pessoa.idade < 1 || pessoa.idade > 120 ||
                                                                                                                                                                                                                                                            pessoa.altura < 0.5 || pessoa.altura > 2.5 ||
                                                                                                                                                                                                                                                                        pessoa.peso < 2 || pessoa.peso > 500
                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                            erro.textContent = "Digite valores válidos!";
                                                                                                                                                                                                                                                                                                        erro.hidden = false;
                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                    if (editando === -1) {
                                                                                                                                                                                                                                                                                                                                                pessoas.push(pessoa);
                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                    pessoas[editando] = pessoa;
                                                                                                                                                                                                                                                                                                                                                                                editando = -1;
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                form.reset();
                                                                                                                                                                                                                                                                                                                                                                                                        erro.hidden = true;

                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btn-salvar").textContent = "Salvar";
                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btn-cancelar").hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("titulo-form").textContent = "Nova pessoa";

                                                                                                                                                                                                                                                                                                                                                                                                                                        atualizarTabela();
                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                function atualizarTabela() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabela.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas.forEach(function (pessoa, index) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const imc = pessoa.peso / (pessoa.altura * pessoa.altura);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let classificacao;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (imc < 18.5) classificacao = "Abaixo do peso";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (imc < 25) classificacao = "Peso normal";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else if (imc < 30) classificacao = "Sobrepeso";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (imc < 35) classificacao = "Obesidade grau I";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (imc < 40) classificacao = "Obesidade grau II";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else classificacao = "Obesidade grau III";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const valores = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.idade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.altura.toFixed(2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.peso.toFixed(1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        imc.toFixed(2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        classificacao
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                valores.forEach(function (valor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const coluna = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coluna.textContent = valor;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.appendChild(coluna);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const acoes = document.createElement("td");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const editar = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                editar.textContent = "Editar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            editar.type = "button";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        editar.onclick = function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("input-nome").value = pessoa.nome;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("input-idade").value = pessoa.idade;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("input-altura").value = pessoa.altura;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("input-peso").value = pessoa.peso;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        editando = index;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btn-salvar").textContent = "Alterar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btn-cancelar").hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("titulo-form").textContent = "Editar pessoa";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const excluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            excluir.textContent = "Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        excluir.type = "button";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    excluir.onclick = function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoas.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarTabela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            acoes.appendChild(editar);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes.appendChild(excluir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    linha.appendChild(acoes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btn-cancelar").onclick = function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                editando = -1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btn-salvar").textContent = "Salvar";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btn-cancelar").hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("titulo-form").textContent = "Nova pessoa";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                erro.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    